381	    /**
382	     * The number of existing owners registered in {@code city}, compared case-insensitively
383	     * with collapsed whitespace.
384	     */
385	    private int countOwnersInCity(String city) {
386	        String normalized = normalizeHouseholdField(city);
387	        return (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
389	            .count();
390	    }
391	
392	    /**
393	     * The effective registration date to store for a new owner: the date supplied on the request
394	     * when present, otherwise the current server date, in either case rolled forward to a business
395	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
396	     * This single point of resolution is what every registration-date-derived value (the stored
397	     * date, the membership number's year segment, the per-day create-limit) is computed from.
398	     */
399	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
400	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
401	        return toBusinessDay(date);
402	    }
403	
404	    /**
405	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
406	     * following Monday; a weekday is returned unchanged.
407	     */
408	    private static LocalDate toBusinessDay(LocalDate date) {
409	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
410	            date = date.plusDays(1);
411	        }
412	        return date;
413	    }
414	
415	    /**
416	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
417	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
418	     */
419	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
420	        String yy = String.format("%02d", registrationDate.getYear() % 100);
421	        return customerCode + "-M" + yy;
422	    }
423	
424	    /**
425	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
426	     * last name, compared case-insensitively.
427	     */
428	    private int countNamesakes(Owner owner) {
429	        String firstName = normalizeHouseholdField(owner.getFirstName());
430	        String lastName = normalizeHouseholdField(owner.getLastName());
431	        return (int) this.clinicService.findAllOwners().stream()
432	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
433	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
434	            .count();
435	    }
436	
437	    /**
438	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
439	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
440	     * unusually high daily signup volume.
441	     */
442	    private boolean isBulkSignupWarning() {
443	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
444	    }
445	
446	    /** The number of existing owners whose registration date is {@code date}. */
447	    private int countOwnersRegisteredOn(LocalDate date) {
448	        return (int) this.clinicService.findAllOwners().stream()
449	            .filter(existing -> date.equals(existing.getRegistrationDate()))
450	            .count();
451	    }
452	
453	    /**
454	     * The single derived key all duplicate detection flows through, formed from the owner's
455	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
456	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
457	     * id is derived, so the household segment is empty at that point. Because the telephone is part
458	     * of the key, two owners in the same household with different telephones resolve to different
459	     * keys and are both allowed.
460	     */
461	    private static String identityKey(Owner owner) {
462	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
463	        String email = owner.getEmail() == null ? "" : owner.getEmail();
464	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
465	        return telephone + "|" + email + "|" + household;
466	    }
467	
468	    /**
469	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
470	     * duplicate condition: the previously separate telephone, email and household checks are now all
471	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
472	     * trips it is rejected with {@code 409 CONFLICT}.
473	     */
474	    private boolean isDuplicate(Owner owner) {
475	        String key = owner.getIdentityKey();
476	        return this.clinicService.findAllOwners().stream()
477	            .map(Owner::getIdentityKey)
478	            .filter(existing -> existing != null)
479	            .anyMatch(key::equals);
480	    }
481	
482	    /** Common street-type abbreviations expanded during address normalization. */
483	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
484	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
485	
486	    /**
487	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
488	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
489	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
490	     * string when {@code address} is null or blank after normalization.
491	     */
492	    private static String normalizeAddress(String address) {
493	        if (address == null) {
494	            return "";
495	        }
496	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
497	        if (collapsed.isEmpty()) {
498	            return "";
499	        }
500	        StringBuilder sb = new StringBuilder(collapsed.length());
501	        for (String token : collapsed.split(" ")) {
502	            if (sb.length() > 0) {
503	                sb.append(' ');
504	            }
505	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
506	        }
507	        return sb.toString();
508	    }
509	
510	    /**
511	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
512	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
513	     */
514	    private static String normalizeHouseholdField(String value) {
515	        if (value == null) {
516	            return "";
517	        }
518	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
519	    }
520	
521	    /**
522	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
523	     * same address compared case-insensitively with collapsed whitespace.
524	     */
525	    private List<Owner> findHousemates(Owner owner) {
526	        String lastName = normalizeHouseholdField(owner.getLastName());
527	        String address = normalizeHouseholdField(owner.getAddress());
528	        return this.clinicService.findAllOwners().stream()
529	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
530	                && normalizeHouseholdField(existing.getAddress()).equals(address))
531	            .toList();
532	    }
533	
534	    /**
535	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
536	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
537	     */
538	    private int countHouseholdMembers(Owner owner) {
539	        return findHousemates(owner).size() + 1;
540	    }
541	
542	    /**
543	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
544	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
545	     * deterministically from those normalized fields so housemates always resolve to the same value,
546	     * regardless of registration order.
547	     */
548	    private static String householdId(Owner owner) {
549	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
550	            + normalizeHouseholdField(owner.getAddress());
551	        return sha256Hex(key).substring(0, 24);
552	    }
553	
554	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
555	    private static String sha256Hex(String input) {
556	        try {
557	            byte[] digest = MessageDigest.getInstance("SHA-256")
558	                .digest(input.getBytes(StandardCharsets.UTF_8));
559	            StringBuilder sb = new StringBuilder(digest.length * 2);
560	            for (byte b : digest) {
561	                sb.append(String.format("%02X", b));
562	            }
563	            return sb.toString();
564	        }
565	        catch (NoSuchAlgorithmException e) {
566	            throw new IllegalStateException("SHA-256 not available", e);
